## Implementation

### File: `src/mcp/index.ts` — main MCP server

```typescript
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';

export async function startMcpProxy(options: McpProxyOptions): Promise<void> {
  const upstream = await resolveAndSpawnUpstream(options);
  const checkpointHandler = new CheckpointToolHandler(options);

  const server = new Server({
    name: 'playwright-checkpoint',
    version: VERSION,
  }, {
    capabilities: { tools: {} },
  });

  // tools/list: merge upstream + checkpoint tools
  server.setRequestHandler(ListToolsRequestSchema, async () => {
    const upstreamTools = await upstream.listTools();
    return {
      tools: [...upstreamTools, ...checkpointHandler.toolDefinitions],
    };
  });

  // tools/call: route to correct handler
  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    if (checkpointHandler.handles(request.params.name)) {
      return checkpointHandler.call(request.params);
    }
    return upstream.callTool(request.params);
  });

  // All other methods (resources, prompts, etc): forward to upstream
  // ...

  const transport = new StdioServerTransport();
  await server.connect(transport);
}
```

### File: `src/mcp/upstream.ts` — upstream detection and spawning

```typescript
interface UpstreamConnection {
  listTools(): Promise<Tool[]>;
  callTool(params: CallToolParams): Promise<CallToolResult>;
  close(): Promise<void>;
}

async function resolveUpstream(options: McpProxyOptions): Promise<string> {
  // Priority order:
  // 1. Explicit --upstream flag
  // 2. Detect installed: @playwright/mcp
  // 3. Detect installed: playwright-mcp-advanced
  // 4. null (standalone mode)

  if (options.upstream) return options.upstream;

  try { await import.meta.resolve('@playwright/mcp'); return '@playwright/mcp'; } catch {}
  try { await import.meta.resolve('playwright-mcp-advanced'); return 'playwright-mcp-advanced'; } catch {}

  return null; // standalone mode
}

async function spawnUpstream(
  pkg: string, 
  passthrough: string[]
): Promise<UpstreamConnection> {
  // Spawn upstream as child process with stdio transport
  const child = spawn('npx', [pkg, ...passthrough], {
    stdio: ['pipe', 'pipe', 'inherit'], // stdin/stdout for JSON-RPC, stderr passthrough
  });

  // Create MCP client connection to child's stdin/stdout
  const client = new Client({ name: 'checkpoint-proxy', version: VERSION });
  const transport = new StdioClientTransport({ reader: child.stdout, writer: child.stdin });
  await client.connect(transport);

  return {
    async listTools() {
      const result = await client.request({ method: 'tools/list' });
      return result.tools;
    },
    async callTool(params) {
      return client.request({ method: 'tools/call', params });
    },
    async close() {
      await client.close();
      child.kill();
    },
  };
}
```

### File: `src/mcp/tools.ts` — checkpoint tool definitions and handler

```typescript
import { captureCheckpoint, createCheckpointSession } from '../core.js';

const CHECKPOINT_TOOLS = [
  {
    name: 'browser_checkpoint',
    description: 'Capture a structured page snapshot. Returns accessibility violations, web vitals, console errors, network failures, metadata, and screenshot path. Much richer than browser_snapshot — gives you actionable diagnostics, not just a DOM tree.',
    inputSchema: {
      type: 'object',
      properties: {
        name: { 
          type: 'string', 
          description: 'Descriptive checkpoint name (e.g. "after-login", "checkout-form")' 
        },
        description: { 
          type: 'string', 
          description: 'What this checkpoint represents (used for documentation generation)' 
        },
        collectors: {
          type: 'object',
          description: 'Enable/disable specific collectors. All enabled by default.',
          properties: {
            screenshot: { type: 'boolean', default: true },
            axe: { type: 'boolean', default: true },
            metadata: { type: 'boolean', default: true },
            webVitals: { type: 'boolean', default: true },
            console: { type: 'boolean', default: true },
            network: { type: 'boolean', default: true },
            html: { type: 'boolean', default: true },
          },
        },
        highlightSelector: {
          type: 'string',
          description: 'CSS selector for the element to highlight in screenshot annotations',
        },
      },
      required: ['name'],
    },
  },
  {
    name: 'browser_checkpoint_report',
    description: 'Generate an HTML report from all checkpoints captured in this session. Returns the report file path.',
    inputSchema: {
      type: 'object',
      properties: {
        outputDir: {
          type: 'string',
          description: 'Directory for the report. Default: ./checkpoint-report',
        },
        format: {
          type: 'string',
          enum: ['html', 'markdown', 'mdx'],
          description: 'Report format. Default: html',
        },
      },
    },
  },
  {
    name: 'browser_checkpoint_compare',
    description: 'Compare two checkpoints and return a structured diff. Highlights changes in accessibility, performance, console errors, and visual differences.',
    inputSchema: {
      type: 'object',
      properties: {
        baseline: { type: 'string', description: 'Name of the baseline checkpoint' },
        current: { type: 'string', description: 'Name of the current checkpoint to compare' },
      },
      required: ['baseline', 'current'],
    },
  },
];

class CheckpointToolHandler {
  private session: CheckpointSession | null = null;
  private page: Page | null = null;

  constructor(private options: McpProxyOptions) {}

  get toolDefinitions() { return CHECKPOINT_TOOLS; }

  handles(name: string) { 
    return CHECKPOINT_TOOLS.some(t => t.name === name); 
  }

  async call(params: CallToolParams): Promise<CallToolResult> {
    switch (params.name) {
      case 'browser_checkpoint':
        return this.handleCheckpoint(params.arguments);
      case 'browser_checkpoint_report':
        return this.handleReport(params.arguments);
      case 'browser_checkpoint_compare':
        return this.handleCompare(params.arguments);
    }
  }

  private async handleCheckpoint(args: Record<string, unknown>) {
    // Lazy-init: connect to browser via CDP on first checkpoint call
    if (!this.page) {
      this.page = await this.connectToBrowser();
    }

    // Lazy-init: create session on first call
    if (!this.session) {
      this.session = await createCheckpointSession(this.page, {
        outputDir: this.options.outputDir ?? './checkpoints',
        collectors: this.resolveCollectors(args.collectors),
      });
    }

    const record = await this.session.checkpoint(args.name as string, {
      description: args.description as string,
      highlightSelector: args.highlightSelector as string,
      collectors: this.resolveCollectors(args.collectors),
    });

    // Return structured summary that's useful to the LLM
    return {
      content: [{
        type: 'text',
        text: this.formatCheckpointSummary(record),
      }],
    };
  }

  private formatCheckpointSummary(record: CheckpointRecord): string {
    // Format a human/LLM-readable summary:
    // - URL, title
    // - Axe: N violations (X critical, Y serious)
    // - Web Vitals: LCP 2.4s (good), CLS 0.05 (good), INP 180ms (needs improvement)
    // - Console: N errors
    // - Network: N failed requests
    // - Screenshot: saved to ./checkpoints/homepage/page.png
    // This structured text is what makes checkpointing WAY more useful than browser_snapshot
  }

  private async connectToBrowser(): Promise<Page> {
    // Strategy 1: CDP endpoint provided explicitly
    // Strategy 2: Detect from upstream (read CDP URL from browser_navigate response)
    // Strategy 3: Connect to well-known CDP port (9222)
    //
    // The upstream @playwright/mcp manages the browser.
    // We connect to it as a secondary client via CDP.
    // Playwright supports multiple CDP sessions on the same browser.
  }
}
```

### Browser connection strategy

The trickiest part is getting a Page handle for the same browser the upstream controls. Options:

**Option A: CDP endpoint detection (preferred)**
- When upstream starts, intercept its stderr for CDP endpoint URL (Chrome prints `DevTools listening on ws://...`)
- Connect with `playwright.chromium.connectOverCDP(endpoint)`
- Get the active page from the browser context

**Option B: Upstream exposes CDP via tool**
- Call `browser_evaluate` with a dummy script to verify connection
- Use the upstream's `browser_network_requests` to get page URL
- Connect via CDP separately

**Option C: Shared user-data-dir**
- Both upstream and checkpoint server use the same `--user-data-dir`
- Upstream manages browser, we attach via CDP debug port
- Pass `--remote-debugging-port=9222` to upstream via passthrough args

**Option D: Page injection from upstream response**
- Some tools return page state. We can infer the active page's URL and connect.
- Fallback: use `browser_evaluate` via upstream to inject a CDP getter.

Recommend starting with Option A (CDP stderr detection) + Option C (debugging port) as fallback.

### File: `src/mcp/browser-connect.ts`

```typescript
export async function connectToUpstreamBrowser(
  upstreamProcess: ChildProcess,
  options: { cdpEndpoint?: string; debugPort?: number }
): Promise<{ browser: Browser; page: Page }> {
  // 1. Try explicit CDP endpoint
  if (options.cdpEndpoint) {
    const browser = await chromium.connectOverCDP(options.cdpEndpoint);
    const pages = browser.contexts()[0]?.pages() ?? [];
    return { browser, page: pages[0] ?? await browser.contexts()[0].newPage() };
  }

  // 2. Parse CDP endpoint from upstream stderr
  const cdpUrl = await detectCdpFromStderr(upstreamProcess, 10_000);
  if (cdpUrl) {
    const browser = await chromium.connectOverCDP(cdpUrl);
    const pages = browser.contexts()[0]?.pages() ?? [];
    return { browser, page: pages[0] ?? await browser.contexts()[0].newPage() };
  }

  // 3. Try well-known debug port
  const debugPort = options.debugPort ?? 9222;
  try {
    const browser = await chromium.connectOverCDP(`http://localhost:${debugPort}`);
    const pages = browser.contexts()[0]?.pages() ?? [];
    return { browser, page: pages[0] ?? await browser.contexts()[0].newPage() };
  } catch {
    throw new Error(
      'Could not connect to browser. Pass --cdp-endpoint or ensure upstream emits CDP URL on stderr.'
    );
  }
}

function detectCdpFromStderr(proc: ChildProcess, timeoutMs: number): Promise<string | null> {
  return new Promise((resolve) => {
    const timer = setTimeout(() => resolve(null), timeoutMs);
    proc.stderr?.on('data', (chunk: Buffer) => {
      const match = chunk.toString().match(/DevTools listening on (ws:\/\/\S+)/);
      if (match) {
        clearTimeout(timer);
        resolve(match[1]);
      }
    });
  });
}
```

